import { topics, dimensions, experts, createMezo, decidePattern, startExperiment, advanceExperiment, acceptCandidate, correctClaim, forecastScore, matchesSearch } from './mezo-state.js';
import { icon, safe, react, toast } from './nap.js';
let state=createMezo(),callbacks,patternFilter='all',forecastFilter='all',factQuery='',memoryQuery='',conferenceMode='decisions';
const roots=['Felfedezések','Előrejelzések','Karakter','Tudástár'];
const statusName={new:'Új észrevétel',watching:'Figyeljük',gathering:'Még gyűlik',confirmed:'Megerősítetted',rejected:'Elvetve',pending:'Még nyitott',hit:'Bevált',missed:'Nem vált be',active:'Folyamatban',completed:'Lezárult'};
const path=(page,view='',id='')=>`#mezo/${page}${view?'/'+view:''}${id?'/'+id:''}`;
const attr=(p,v='',id='')=>`data-mz-link="${path(p,v,id)}"`;
const pill=(text,tone='')=>`<span class="mz-pill ${tone}">${text}</span>`;
const pills=items=>`<div class="mz-pills">${items.map(t=>pill(t)).join('')}</div>`;
const action=(text,attrs='',secondary=false)=>`<button class="mz-action ${secondary?'secondary':''}" ${attrs}>${text}</button>`;
const link=(art,title,sub,p,v='',id='')=>`<button class="mz-door" ${attr(p,v,id)}>${icon(art)}<span><strong>${title}</strong><small>${sub}</small></span><b>↗</b></button>`;
const heading=(eyebrow,title,copy='',art='gem')=>`<div class="mz-heading">${icon(art)}<span class="overline">${eyebrow}</span><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div>`;
const note=text=>`<div class="mz-note">${icon('chat')}<p>${text}</p></div>`;
const foot=()=>`<p class="mz-foot">INTERAKTÍV MINTAVILÁG · A történetek, értékek és AI-szövegek bemutatóadatok. A válaszaid itt csak a demót alakítják; újratöltéskor törlődnek.</p>`;
const split=(title,sub='')=>`<div class="mz-section"><h2>${title}</h2><span>${sub}</span></div>`;
const stats=items=>`<div class="mz-stats">${items.map(([n,l])=>`<span><strong>${n}</strong><small>${l}</small></span>`).join('')}</div>`;
function constellation(){return `<svg class="mz-constellation" viewBox="0 0 340 180" aria-hidden="true"><defs><radialGradient id="mz-aura"><stop stop-color="#bca6f1" stop-opacity=".24"/><stop offset="1" stop-color="#bca6f1" stop-opacity="0"/></radialGradient></defs><ellipse cx="170" cy="90" rx="150" ry="90" fill="url(#mz-aura)"/><g stroke="#bca6f13a" fill="none"><path d="M54 50L170 88 282 40 244 143 92 142 54 50 244 143M92 142L170 88 244 143M282 40L54 50"/><ellipse cx="170" cy="90" rx="130" ry="56" transform="rotate(-15 170 90)"/></g>${[[54,50,12,'purple'],[170,88,22,'titanium'],[282,40,10,'blue'],[244,143,14,'gold'],[92,142,9,'lime']].map(([x,y,r,c])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="url(#${c})" stroke="#ffffff36"/>`).join('')}<circle class="mz-signal" cx="170" cy="88" r="6" fill="#e9d3a4"/></svg>`;}
function poster(t){return `<button class="mz-poster" style="--mz-color:${t.color}" ${attr(0,'pattern',t.id)}><span class="mz-poster-top">${pill(statusName[state.patterns[t.id]],state.patterns[t.id])}<span>${t.days} közös mintanap</span></span>${icon(t.icon)}<h2>${t.title}</h2><p>${t.question}</p><span class="mz-poster-foot">${t.domains.join(' × ')}<b>↗</b></span></button>`;}
function filter(kind,options,current){return `<div class="mz-filters" aria-label="Szűrés">${options.map(([key,name])=>`<button data-mz-filter="${kind}" data-value="${key}" aria-pressed="${current===key}">${name}</button>`).join('')}</div>`;}
function overview(){const pending=topics.filter(t=>state.patterns[t.id]==='new').length;return `<div class="mz-intro-line"><span class="overline">A KÖZÖS FELFEDEZÉSEINK</span><p>Amit észreveszünk, annak együtt járunk utána.</p></div>${stats([[pending,'új észrevétel'],[topics.filter(t=>state.patterns[t.id]==='watching').length,'figyelt minta'],[state.experiments.filter(e=>e.status==='active').length,'aktív kísérlet']])}${link('chat','Járjunk utána','Fáradtság, alvás — egy kérdésből indulunk.',0,'investigate')}${split('Összeérő szálak','3 TÉMA')}${filter('patterns',[['all','Mind'],['new','Új'],['watching','Figyelt'],['confirmed','Megerősített'],['rejected','Elvetett']],patternFilter)}<div id="mz-pattern-list">${topics.filter(t=>patternFilter==='all'||state.patterns[t.id]===patternFilter).map(poster).join('')||empty('Itt most nincs minta.','A többi szálat a Mind szűrő alatt találod.')}</div>${split('Amit kipróbálunk')}${experimentCards()}${link('bolt','Mikor szól Mezo?','Coaching, csend és a javaslat mögötti okok.',0,'coaching')}${link('stack','Miből látunk ennyit?','Adatlefedettség és hiányzó jelek.',0,'coverage')}`;}
function empty(title,text){return `<div class="mz-empty">${icon('ring')}<h3>${title}</h3><p>${text}</p></div>`;}
function experimentCards(){return state.experiments.length?state.experiments.map(e=>{const t=topics.find(t=>t.id===e.topic);return link('ring',t.experiment,`${statusName[e.status]} · ${e.day}/7 mintanap`,0,'experiment',t.id);}).join(''):empty('Még nem indítottunk kísérletet.','Nyiss meg egy témát, és nézd meg, mit lehetne egyszerűen kipróbálni.');}
function chart(t){return `<figure class="mz-evidence-chart"><figcaption>${t.id==='load'?'Vállból nyomás · ismétlésszám':t.measure}<br>Szemléltető mintarészlet</figcaption><div class="mz-chart-columns">${t.a.map((a,i)=>`<div><span style="height:${a*7}px" title="A: ${a}"></span><span style="height:${t.b[i]*7}px" title="B: ${t.b[i]}"></span></div>`).join('')}</div><div class="mz-chart-key"><span>A · ${t.id==='evening'?'későbbi vacsora':t.id==='load'?'röplabda után':'rutin nélkül'}</span><span>B · ${t.id==='evening'?'korábbi vacsora':t.id==='load'?'más edzésnap':'rutinnal'}</span></div><details><summary>Számok szövegesen</summary><p>A: ${t.a.join(', ')}<br>B: ${t.b.join(', ')}</p></details></figure>`;}
function pattern(id){const t=topics.find(t=>t.id===id);if(!t)return missing();const status=state.patterns[id];return heading('EGY TÉMA · EGY KÖZÖS TÖRTÉNET',t.title,t.question,t.icon)+pills([statusName[status],`${t.days} közös mintanap`,...t.domains])+`<div class="mz-story"><span class="overline">AMIT EDDIG LÁTUNK</span><p>${t.finding}</p></div>`+chart(t)+`<div class="mz-caution"><strong>Amit ebből még nem tudunk</strong><p>${t.limit}</p></div>`+split('Neked ismerős?')+`<div class="mz-decisions">${[['confirmed','Igen, talál'],['watching','Figyeljük még'],['rejected','Nem stimmel']].map(([v,l])=>`<button data-mz-pattern="${id}" data-decision="${v}" aria-pressed="${status===v}">${l}</button>`).join('')}</div>`+(status==='confirmed'?note('A megerősített minta megjelent a Tudástárban. A bizonyítékai továbbra is ezen az oldalon maradnak.')+link('stack','A kapcsolódó tudás','Megnézheted, használható-e a beszélgetésben.',3,'fact','pattern-'+id):status==='rejected'?note('Elvetetted ezt a mintát. A hozzá kapcsolt tudás felhasználását kikapcsoltuk a demóban.'):note('A bizonytalanság is része a közös képnek. Egy megfigyelt kapcsolat még nem bizonyított ok.'))+split('Következő lépés')+link('ring',t.experiment,'Egyetlen változtatás · hét nap · visszanézhető eredmény.',0,'experiment',id)+link('sun','Mi következhet ebből?','A kapcsolódó előrejelzés és annak visszamérése.',1,'forecast',id==='evening'?'sleep':id==='load'?'strength':'routine')+link('book','Forrásnapok','Nézd meg, milyen napokból indultunk.',3,'memory')+link('chat','Beszéljük át ezt a témát','Kérdésindítók a megfigyelés kontextusával.',0,'talk',id);}
function investigate(id){if(!id)return heading('JÁRJUNK UTÁNA','Mi foglalkoztat most?','Egy konkrét kérdésből indulunk. Összerakjuk a jeleket, és külön mutatjuk a lehetséges magyarázatokat.','chat')+link('bolt','Miért vagyok fáradt?','Alvás, terhelés és étkezés együtt.',0,'investigate','fatigue')+link('moon','Miért változott az alvásom?','Esti ritmus és a napod eseményei.',0,'investigate','sleep')+note('A korábbi „Diagnózis” itt él tovább. A cél lehetséges magyarázatok keresése és ellenőrizhető következő lépés.')+split('Korábbi vizsgálat')+link('book','Egy sűrű hét tanulságai','Lezárt mintavizsgálat · augusztus 30.',0,'investigate','archive');const fatigue=id!=='sleep';return heading('VIZSGÁLAT · DEMÓJELENTÉS',id==='archive'?'Egy sűrű hét.':fatigue?'Nézzük meg a fáradtságot.':'Mi változott az estéidben?', 'Három nézőpont. Mindegyiknél látszik, mi támasztja alá, és mi maradt nyitva.',fatigue?'bolt':'moon')+stats([['14','mintanap'],['3','adatkör'],['2','nyitott kérdés']])+`<div class="mz-case"><span class="overline">01 · LEHETSÉGES MAGYARÁZAT</span><h2>${fatigue?'Egymásra torlódó terhelés':'Későbbre csúszó vacsorák'}</h2><p>${fatigue?'A példahéten gym és röplabda is szerepel egymás melletti napokon.':'A mintanapokban több késői étkezés mellé gyengébb alvásminőség került.'}</p>${pills(['Több jel együtt','Oki kapcsolat nem igazolt'])}${link('gem','A kapcsolódó minta','Bizonyítékok és saját visszajelzés.',0,'pattern',fatigue?'load':'evening')}</div><div class="mz-case"><span class="overline">02 · ÉRDEMES MEGNÉZNI</span><h2>A pihenés ritmusa</h2><p>Az alvás hossza mellett annak időzítése és a saját minőségértékelésed is számít a képben.</p><button class="mz-inline" data-route="me/2">Alvásnapló megnyitása ↗</button></div><div class="mz-caution"><strong>03 · Kevés a támpont</strong><p>A mentális terhelésről csak néhány check-in áll rendelkezésre. Ezt nem tölti ki Mezo feltételezéssel.</p></div>`+note('A bemutatójelentés nem állapít meg biztos okot. A következő lépés egy kis, megfigyelhető változtatás.')+link('ring','Próbáljuk ki egy héten át','Korábbi vacsora és reggeli alvás-visszajelzés.',0,'experiment','evening');}
function experiment(id){const t=topics.find(t=>t.id===id);if(!t)return heading('KÍSÉRLETEK','Apró változtatások.','A folyamatban lévő és lezárt próbáink egy helyen.','ring')+experimentCards()+topics.map(t=>link(t.icon,t.experiment,t.measure,0,'experiment',t.id)).join('');const e=state.experiments.find(e=>e.topic===id);return heading('SAJÁT KÍSÉRLET',t.experiment,t.probe,'ring')+pills([e?statusName[e.status]:'Javaslat','7 nap',t.measure])+`<div class="mz-method"><h3>Így néznénk meg</h3><ol><li>Egy dolgon változtatsz.</li><li>Minden nap ugyanazt a jelzést figyeljük.</li><li>A végén az előző időszakhoz hasonlítunk.</li></ol><p>Ha közben más is változik, azt a jegyzetedben tudod jelezni.</p></div>`+(!e?action('Kipróbálom · kísérlet indítása',`data-mz-start="${id}"`):`<div class="mz-experiment-progress"><strong>${e.day}<small> / 7 mintanap</small></strong><div>${Array.from({length:7},(_,i)=>`<span class="${i<e.day?'done':''}">${i<e.day?'✓':i+1}</span>`).join('')}</div></div>`+(e.status==='active'?`<div class="mz-simulator"><span class="overline">DEMO IDŐUGRÁS</span><p>A valódi hét helyett itt előreléptetheted a mintafolyamatot. Ez nem naplóz valós adatot.</p>${action('Eltelt egy mintanap →',`data-mz-advance="${id}"`,true)}</div>`:`<div class="mz-outcome"><span class="overline">EREDMÉNY · VEGYES KÉP</span><h2>Tanultunk belőle. Még nincs biztos válasz.</h2><p>A demóban néhány nap kedvezőbb, más napok nem változtak. Hét napból nem hirdetünk bizonyított összefüggést.</p>${chart(t)}</div>`)+`<form data-mz-experiment-note="${id}"><label class="mz-label">Mi történt közben?<textarea name="note" maxlength="1500" placeholder="Egy körülmény, ami számíthat…">${safe(e.note)}</textarea></label>${action('Jegyzet mentése','type="submit"',true)}</form>`)+link('gem','Vissza az eredeti mintához',t.short,0,'pattern',id);}
function predictions(){const score=forecastScore(state);return heading('ELŐREJELZÉSEK','Előre nézünk.<br>Utána vissza is.','A várakozás mellé odatesszük, ami ténylegesen történt.','sun')+stats([[state.forecasts.filter(f=>f.status==='pending').length,'még nyitott'],[`${score.hit}/${score.closed}`,'lezártból bevált'],['tanulom','bizonyosság']])+filter('forecasts',[['all','Mind'],['pending','Nyitott'],['closed','Visszamért']],forecastFilter)+state.forecasts.filter(f=>forecastFilter==='all'||(forecastFilter==='closed'?f.status!=='pending':f.status==='pending')).map(f=>`<button class="mz-forecast" ${attr(1,'forecast',f.id)}>${pill(statusName[f.status],f.status)}<small>${f.window}</small><h2>${f.title}</h2><p>${f.actual||f.expected}</p><span>${f.status==='pending'?'Mire alapozzuk?':'Várakozás és eredmény'} ↗</span></button>`).join('')+note('A találati arány csak a lezárt példákból számolódik. Két visszamérés kevés ahhoz, hogy a rendszer pontosságáról biztos következtetést vonjunk le.');}
function forecast(id){const f=state.forecasts.find(f=>f.id===id);if(!f)return missing();return heading('ELŐREJELZÉS · '+f.window,f.title,'A jövőre vonatkozó feltevés, nem ígéret.','sun')+pills([statusName[f.status],'Bizonyosság: tanulom'])+`<div class="mz-compare"><section><span class="overline">AMIRE SZÁMÍTOTTUNK</span><p>${f.expected}</p></section><section><span class="overline">AMI TÖRTÉNT</span><p>${f.actual||'Az időablak még nyitott. Nincs lezárt eredmény.'}</p></section></div>`+link('gem','Az előrejelzés alapja',topics.find(t=>t.id===f.topic).short,0,'pattern',f.topic)+split('Hasznos volt ez neked?')+`<div class="mz-decisions"><button data-mz-feedback="${id}" data-value="yes" aria-pressed="${state.feedback[id]==='yes'}">Igen, segített</button><button data-mz-feedback="${id}" data-value="no" aria-pressed="${state.feedback[id]==='no'}">Nem igazán</button></div>`+note('A hasznossági visszajelzésed külön dolog attól, hogy az előrejelzés bevált-e. Nem írja át az eredményt.')+link('ring','Kapcsolódó kísérlet','Egy változtatás, amit együtt követhetünk.',0,'experiment',f.topic);}
function character(){const active=state.claims.filter(c=>c.status==='active').length;return heading('KARAKTER','Egy alakuló kép.<br>Rólad, veled.','Amit eddig megértettem belőled, és ahol még kérdéseim vannak.','person')+constellation()+stats([[7,'nézőpont'],[active,'élő mintaállítás'],[state.claims.filter(c=>c.correction).length,'pontosítás vár']])+note('Ez a te visszajelzéseiddel alakítható portré. A mintaállítások nem a személyiséged mérési eredményei.')+split('A kép részletei')+`<div class="mz-dimension-grid">${dimensions.map(([id,name,art,color,copy])=>`<button style="--mz-color:${color}" ${attr(2,'dimension',id)}>${icon(art)}<strong>${name}</strong><p>${copy}</p><small>${state.claims.find(c=>c.id===id).status==='retired'?'Állítás visszavonva':state.claims.find(c=>c.id===id).confidence} ↗</small></button>`).join('')}</div>`+link('chat','A legutóbbi konzílium','Mi változott, miért, és miben nem értettek egyet?',2,'conference')+link('person','A csapat nézőpontjai','Kilenc szerep, egy közös társ.',2,'team')+link('book','Ahogy alakul a kép','Megfigyelések és a te visszajelzéseid.',2,'feed')+link('stack','Mezo önvizsgálata','A rendszer bizonytalanságai és működése.',2,'audit');}
function dimension(id){const d=dimensions.find(d=>d[0]===id),c=state.claims.find(c=>c.id===id);if(!d||!c)return missing();return heading('KARAKTER · EGY NÉZŐPONT',d[1],d[4],d[2])+`<div class="mz-portrait"><span class="overline">A JELENLEGI PORTRÉRÉSZLET</span><p>${id==='people'?'Erről még kevés személyes történet áll rendelkezésre. A hiányt nem töltjük ki egy kitalált portréval.':`A mintavilágban ${d[1].toLowerCase()} témája több nap történetében visszatér. Az alábbi állítás egy ellenőrizhető darab ebből a képből.`}</p></div><div class="mz-claim ${c.status==='retired'?'retired':''}">${pill(c.status==='retired'?'Visszavontad':c.confidence)}<h2>${safe(c.text)}</h2><p>Forrás: bemutató beszélgetések és napösszegzések. Nem pszichológiai teszt.</p>${c.status==='retired'?note('Ezt már nem kezeljük élő állításként a demóban.'):`<div class="mz-decisions"><button data-mz-claim="${id}" data-value="agree" ${c.feedback==='agree'?'disabled':''}>${c.feedback==='agree'?'Köszönöm ✓':'Talál'}</button><button data-mz-claim="${id}" data-value="reject">Nem igaz</button><button data-mz-focus="claim-correction">Pontosítom</button></div>`}</div>${c.correction?`<div class="mz-caution"><strong>A pontosításod feldolgozásra vár</strong><p>${safe(c.correction)}</p><small>Az eredeti állítást nem írjuk át automatikusan a beküldött szövegből.</small></div>`:''}<form data-mz-correction="${id}"><label class="mz-label">A te szavaiddal<textarea id="claim-correction" name="text" maxlength="1500" required placeholder="Inkább úgy mondanám, hogy…"></textarea></label>${action('Pontosítás elküldése','type="submit"',true)}</form>`+link('book','A kapcsolódó emlékek','Nézd meg a mintaelőzményeket.',3,'memory')+link('chat','Hogyan születik egy állítás?','A konzílium döntései és kételyei.',2,'conference');}
function conference(){return heading('KONZÍLIUM · SZEPTEMBER 6.','Nem minden felvetésből lesz állítás.','Előbb megvizsgáljuk a bizonyítékot, aztán eldöntjük, mi kerüljön a portréba.','chat')+filter('conference',[['decisions','Döntések'],['discussion','Beszélgetés']],conferenceMode)+(conferenceMode==='decisions'?stats([['2','felvetés'],['1','elfogadva'],['1','elvetve']])+`<div class="mz-case"><span class="overline">ELFOGADVA · ÁRNYALVA</span><h2>Konkrét lépések segíthetnek az indulásban.</h2><p>A felvetés helyzetfüggő formában maradt meg. A mintában a sűrű munkanapokról volt elegendő beszélgetés.</p>${link('heart','Belső működés','Az állítást itt tudod pontosítani.',2,'dimension','mind')}</div><div class="mz-caution"><strong>Elvetve: „Mindig merev tervre van szükséged.”</strong><p>A mindig túl erős állítás. Nincs hozzá elég bizonyíték, és ellentmondó példák is vannak.</p></div>`:experts.slice(3,5).concat(experts.slice(7)).map((e,i)=>`<div class="mz-turn"><span>${icon(e[2])}<strong>${e[0]}</strong>${pill(['Felvetés','Árnyalás','Kétely','Döntés'][i])}</span><p>${['A mintabeszélgetésekben a konkrét következő lépés többször segítette az elindulást.','Ez leginkább sűrű munkanapokon jelent meg. A szabadnapokról kevés adatunk van.','A „mindig” állítást nem támogatják a források. A helyzethez kötött, óvatos megfogalmazás maradhat.','A szűkebb értelmezést őrizzük meg, és lehetőséget adunk a pontosításra.'][i]}</p></div>`).join(''))+note('Ez egy előre megírt mintakonzílium. Az éles felületen a tényleges, rögzített vita és döntések jelennének meg.')+link('person','Kik szólnak hozzá?','Szerepek és felelősségek.',2,'team')+link('book','Korábbi konzílium','Egy másik mintadöntés története.',2,'conference-archive');}
function team(id){if(id){const e=experts[Number(id)-1];if(!e)return missing();return heading('A CSAPAT EGY NÉZŐPONTJA',e[0],e[1],e[2])+`<div class="mz-method"><h3>Mit tesz hozzá?</h3><p>A saját területéhez kapcsolódó jeleket foglalja össze. Megmutatja, miből következtet és hol hiányos a kép.</p><h3>Hol találkozol vele?</h3><p>A konzílium és a megfigyelések részleteiben. A közvetlen társad továbbra is Mezo.</p><h3>A szerep határa</h3><p>Ez egy AI-nézőpont a demóban, nem külön emberi szakértő vagy önálló tanácsadó.</p></div>`+link('chat','A közös gondolkodás','Nézd meg a mintakonzíliumot.',2,'conference');}return heading('A CSAPAT','Több nézőpont.<br>Egy közös kép.','A különböző olvasatok találkoznak, a kételyeknek is helyük van.','person')+experts.map((e,i)=>link(e[2],e[0],e[1],2,'team',String(i+1))).join('');}
function feed(){return heading('AHOGYAN A KÉP ALAKUL','A megértésnek nyoma van.','Megfigyelések, döntések és a te pontosításaid.','book')+split('Most · a demóban')+(state.eventLog.length?state.eventLog.slice().reverse().map(e=>`<div class="mz-feed-entry"><span class="overline">A TE VISSZAJELZÉSED</span><p>${safe(e)}</p></div>`).join(''):empty('Még nem válaszoltál állításra.','A dimenziókban jelezheted, mi talál és mi nem.'))+split('Szeptember 6. · mintaelőzmény')+link('chat','Egy állítás árnyaltabb lett','Konzílium · a helyzetfüggő megfogalmazás maradt.',2,'conference')+link('moon','Visszatérő esti ritmus','Megfigyelés · nem állítás.',0,'pattern','evening');}
function audit(){return heading('MEZO ÖNVIZSGÁLATA','A társad is tanul.','A pontosság és a bizonytalanság látható része a kapcsolatnak.','stack')+stats([['1/2','bevált mintaelőrejelzés'],[state.claims.filter(c=>c.status==='retired').length,'visszavont állítás'],[state.claims.filter(c=>c.correction).length,'nyitott pontosítás']])+`<div class="mz-caution"><strong>Kevés visszamérés</strong><p>A bemutató két lezárt előrejelzése nem elegendő egy stabil pontossági értékhez.</p></div>`+link('sun','Előrejelzések visszamérése','A tévedés is ott marad a történetben.',1)+link('stack','Gépterem','Adatforrások, mintafutások és a feldolgozás lépései.',2,'engine');}
function engine(id){if(id==='run')return heading('MINTAFUTÁS · SZEPT. 9. 02:10','Jelből megfigyelés.','Egy bemutatott feldolgozási lánc, végig követhető eredettel.','bolt')+`<ol class="mz-process"><li><strong>Adatjel</strong><p>Étkezési időpont és reggeli alvásértékelés.</p></li><li><strong>Ellenőrzés</strong><p>Van-e elég közös nap? Hiányzó napokat nem nullázunk.</p></li><li><strong>Értelmezés</strong><p>A minták mellett az ellenpéldák is megmaradnak.</p></li><li><strong>Megfigyelés</strong><p>Az esti ritmus kérdésként került eléd.</p></li></ol>`+link('gem','A létrejött megfigyelés','Vacsora × alvás.',0,'pattern','evening');return heading('GÉPTEREM','Lásd, miből dolgozom.','A működés részletei külön helyen, a személyes történet mögött.','stack')+link('bolt','Utolsó mintafutás','4 lépés · adatjelből megfigyelés.',2,'engine','run')+link('ring','Adatforrások és lefedettség','Mi áll rendelkezésre, és mi hiányzik?',0,'coverage')+link('book','Memóriarétegek','Napi történésekből tartós tudás.',3,'layers')+`<div class="mz-method"><h3>Három mintadetektor</h3><p>Étkezési idő × alvás · röplabda × gym · rutin × közérzet.</p><p>A demó nem futtat háttérfeladatokat és nem mutat valós szolgáltatásállapotot vagy költséget.</p></div>`;}
function coverage(){return heading('ADATLEFEDETTSÉG','A hiány is információ.','A mintakeresés a közös napokra támaszkodik. Nem helyettesítjük a hiányt kitalált adatokkal.','stack')+`<div class="mz-coverage">${[['Alvás',18,21,'moon'],['Étkezési idő',18,21,'bowl'],['Edzés-visszajelzés',12,21,'dumbbell'],['Rutin és közérzet',9,21,'ring']].map(([l,n,total,i])=>`<div>${icon(i)}<span><strong>${l}</strong><small>${n} / ${total} mintanap</small><i><b style="width:${n/total*100}%"></b></i></span></div>`).join('')}</div>`+note('A magas lefedettség önmagában még nem tesz igazzá egy mintát. Az együtt változó tényezőket és az ellenpéldákat is meg kell nézni.')+link('gem','A minták bizonyítékai','Innen indult a három közös témánk.',0)+link('stack','Feldolgozási lánc','Mit történik a jelekkel?',2,'engine','run');}
function coaching(){return heading('PROAKTÍV COACHING','Mikor szólok?<br>Mikor maradok csendben?','A figyelemhez az időzítés is hozzátartozik.','bolt')+`<div class="mz-case"><span class="overline">MAI MINTAJAVASLAT</span><h2>Az edzés előtt egy kis ránézés.</h2><p>Ma felsőtest, holnap röplabda. A terhelés és a pihenés közös áttekintése most releváns lehet.</p>${pills(['Időszerű','Van edzésterv','Nem sürgető'])}<button class="mz-action" data-route="train/1">Megnézem a terhelést ↗</button></div>`+link('stack','Miért ezt hozta fel?','A kiválasztott jel, az indok és a csendben maradt témák.',0,'coaching-detail')+note('A bemutató nem küld értesítést és nem módosít edzéstervet. A javaslat egy meglévő oldalra vezet.');}
function coachingDetail(){return heading('EGY JAVASLAT HÁTTERE','Miért pont most?','A döntés olvasható útja.','bolt')+`<ol class="mz-process"><li><strong>Jel</strong><p>Mai gym és holnapi röplabda szerepel a mintanaptárban.</p></li><li><strong>Kapcsolódó állapot</strong><p>Az utolsó alvás megvan; így a terheléshez regenerációs kontextus is társul.</p></li><li><strong>Választott lépés</strong><p>A Terhelés oldal megnyitása. A tervet Mezo nem írja át magától.</p></li><li><strong>Ami csendben maradt</strong><p>A reggeli rutinról kevés közös adat van. Erről most nem állítunk biztosat.</p></li></ol>`+link('ring','A csendben maradt minta','Rutin × közérzet.',0,'pattern','rhythm');}
function knowledge(){return heading('TUDÁSTÁR','Amit magammal viszek<br>a beszélgetéseinkbe.','Tények, emlékek és kapcsolatok. Mindegyiknél látszik, honnan jött.','stack')+stats([[state.facts.length,'megőrzött tény'],[state.facts.filter(f=>f.active).length,'felhasználható'],[state.candidate==='pending'?1:0,'jóváhagyás vár']])+(state.candidate==='pending'?`<div class="mz-candidate"><span class="overline">EZT JÓL ÉRTETTEM?</span><h2>A sűrű napokon rövidebb, konkrét javaslatokat szeretnél.</h2><p>Forrás: bemutató beszélgetés. A jóváhagyásod után kerül a tények közé.</p><div class="mz-decisions"><button data-mz-candidate="accept">Igen, jegyezd meg</button><button data-mz-candidate="reject">Nem így van</button></div></div>`:note(state.candidate==='accepted'?'A jóváhagyott mondat már a tények között van.':'Ezt a jelöltet nem tettük a tények közé.'))+`<div class="mz-search"><label for="mz-fact-search">Keress a tényekben</label><input id="mz-fact-search" type="search" value="${safe(factQuery)}" placeholder="Pl. röplabda, cél, rutin…"></div><div id="mz-fact-results">${factRows()}</div>`+link('gem','Új tényt adok hozzá','A saját szavaiddal, pontosan.',3,'new-fact')+split('Összekapcsolt történetek')+link('ring','Kapcsolatok térképe','Témák, emlékek és a köztük lévő szálak.',3,'graph')+link('book','Emlékek és Memoár','Egy nap részlete és a hosszabb történet.',3,'memory')+link('chat','Így beszélj velem','A saját kommunikációs preferenciád.',3,'tone')+link('stack','Hogyan emlékszik Mezo?','Rétegek, eredet és működési határok.',3,'layers');}
function factRows(){const facts=state.facts.filter(f=>matchesSearch([f.text,f.category,f.source].join(' '),factQuery));return facts.map(f=>link(f.pattern?'gem':'book',safe(f.text),`${f.category} · ${f.active?'felhasználható':'kikapcsolva'}`,3,'fact',f.id)).join('')||empty('Nincs ilyen találat.','Próbálj egy másik szót, vagy adj hozzá saját tényt.');}
function fact(id){const f=state.facts.find(f=>f.id===id);if(!f)return missing();return heading('EGY MEGŐRZÖTT TÉNY',safe(f.text),'Az eredete és a felhasználása egy helyen.','book')+pills([f.category,f.source])+`<button class="mz-toggle" data-mz-toggle="${id}" aria-pressed="${f.active}"><span><strong>Felhasználható a beszélgetésben</strong><small>A tényleges felhasználás a kérdés kontextusától is függ.</small></span><b>${f.active?'BE':'KI'}</b></button>`+(f.pattern?link('gem','A forrásminta','A bizonyíték és a megerősítés ott marad.',0,'pattern',f.pattern):`<div class="mz-method"><h3>Honnan származik?</h3><p>${f.source==='Saját bejegyzés'?'Te írtad be ebben a demóban.':'Előre megadott mintatény a bemutatóhoz.'}</p></div>`)+`<form data-mz-fact-edit="${id}"><label class="mz-label">Pontos megfogalmazás<textarea name="text" maxlength="1000" required>${safe(f.text)}</textarea></label>${action('Pontosítás mentése','type="submit"',true)}</form>`+note('A kikapcsolás nem törli a tényt: megőrzöd, de jelzed, hogy ne legyen felhasználható.');}
const memories=[{id:'tue',date:'Szeptember 8. · kedd',title:'A pálya után',text:'A mintanapban este röplabdáztál. A naplóban azt írtad, jól esett a mozgás, de későre csúszott a vacsora.',tags:'röplabda vacsora mozgás',topic:'evening'},{id:'mon',date:'Szeptember 7. · hétfő',title:'Vissza a ritmusba',text:'A hét első edzése és egy rövid reggeli rutin adta a mintanap két kapaszkodóját.',tags:'edzés rutin reggel',topic:'rhythm'},{id:'sun',date:'Szeptember 6. · vasárnap',title:'Lassabb vasárnap',text:'A bemutatóban egy csendesebb nap zárta a hetet. A következő hétre a fokozatos építkezés maradt a szándék.',tags:'pihenés cél hét',topic:'load'}];
function memory(id){if(id){const m=memories.find(m=>m.id===id);if(!m)return missing();return heading('NAPEMLÉK · '+m.date,m.title,'Egy megőrzött történet a mintavilágból.','book')+`<div class="mz-memoir-text"><p>${m.text}</p><p>Ez a nap önmagában egy epizód. Csak más napokkal és a saját visszajelzéseddel együtt alakíthatja a rólad őrzött képet.</p></div>`+pills(['Forrás: mintaösszegzés','Nem nyers naplóidézet'])+link('gem','A kapcsolódó téma',topics.find(t=>t.id===m.topic).short,0,'pattern',m.topic)+link('book','A hét története','Memoár · több nap összefüggő olvasata.',3,'memoir');}return heading('EMLÉKEK','Egy nap is lehet kapaszkodó.','A mintanapok között kereshetsz; a hosszabb történetet a Memoár fogja össze.','book')+`<div class="mz-search"><label for="mz-memory-search">Keresés a mintaemlékekben</label><input id="mz-memory-search" type="search" value="${safe(memoryQuery)}" placeholder="Pl. röplabda vagy reggel"></div><div id="mz-memory-results">${memoryRows()}</div>`+link('book','A hét története','Memoár és korábbi fejezetek.',3,'memoir')+link('stack','Az emlékek útja','Hogyan kapcsolódik mindez a tudáshoz?',3,'layers');}
function memoryRows(){return memories.filter(m=>matchesSearch(m.title+' '+m.tags+' '+m.text,memoryQuery)).map(m=>link('book',m.title,m.date,3,'memory',m.id)).join('')||empty('Nincs ilyen mintaemlék.','A demó szöveges keresést használ a három bemutató nap között.');}
function memoir(id){const older=id==='older';return heading('MEMOÁR · '+(older?'AUG. 24–30.':'AUG. 31. – SZEPT. 6.'),older?'Újrakezdés, kis lépésekben.':'A ritmus nem mindig egyenes vonal.','Előre megírt bemutatófejezet. A napjaidból összefűzött történet helye.','book')+`<div class="mz-memoir-text"><p>${older?'A mintahét elején sok terv állt egymás mellett. A végére egy kisebb, tartható lépés lett a kapaszkodó.':'Ebben a mintahétben a mozgás többször adott keretet a napnak. A pálya és a gym különböző élmények voltak, mégis ugyanabba a hétbe érkeztek.'}</p><p>A késői esték mellett megjelent a kérdés: miből lesz könnyebb reggel? A válasz még alakul. Ami megmaradt, az a figyelem arra, hogyan függ össze az étkezés, a terhelés és a pihenés.</p><blockquote>„A következő lépés legyen elég kicsi ahhoz, hogy ma is beleférjen.”</blockquote><p>A történetben helye van annak is, ami nem ment a terv szerint. A következő héthez ezek a napok is hozzátartoznak.</p></div>`+split('Szálak ebből a fejezetből')+link('moon','Esti ritmus',topics[0].short,0,'pattern','evening')+link('book','A forrásnapok','A három bemutató nap története.',3,'memory')+link('book',older?'Újabb fejezet':'Korábbi fejezet',older?'A ritmus nem mindig egyenes vonal.':'Újrakezdés, kis lépésekben.',3,'memoir',older?'':'older');}
function graph(id){const t=topics.find(t=>t.id===id);return heading('KAPCSOLATOK TÉRKÉPE',t?t.short:'A szálak összeérnek.',t?'Ugyanaz a téma többféle emlékben és értelmezésben.':'Válassz egy témát: a térkép nem egy második ténylista.','ring')+constellation()+(t?link(t.icon,'A minta saját oldala',t.title,0,'pattern',t.id)+link('book','Kapcsolódó napemlék','A történet kontextusa.',3,'memory',t.id==='evening'?'tue':t.id==='rhythm'?'mon':'sun')+link('person','Kapcsolódó karakterdimenzió','Más nézőpont ugyanarra a témára.',2,'dimension',t.id==='evening'?'body':t.id==='load'?'training':'habits'):topics.map(t=>link(t.icon,t.short,'Minta → emlék → portré',3,'graph',t.id)).join(''))+note('A kapcsolat azt mutatja, hogy két történet összetartozhat. Nem jelenti azt, hogy egyik okozza a másikat.');}
function layers(){return heading('HOGYAN EMLÉKSZEM?','Történetből megértés.','Négy különböző szerep, egy követhető lánc.','stack')+`<ol class="mz-process"><li><strong>01 · Amit rögzítesz</strong><p>Étkezés, edzés, alvás és saját szavak. Ezek az eredeti események.</p><button class="mz-inline" data-route="nap/0">A napod megnyitása ↗</button></li><li><strong>02 · A nap története</strong><p>Az összegzés segít felidézni az adott nap kontextusát.</p><button class="mz-inline" ${attr(3,'memory')}>Emlékek ↗</button></li><li><strong>03 · Amit észreveszünk</strong><p>Kérdések és minták, bizonyítékokkal és bizonytalansággal.</p><button class="mz-inline" ${attr(0)}>Felfedezések ↗</button></li><li><strong>04 · Amit megőrzünk</strong><p>A jóváhagyott tények visszakereshetők és kikapcsolhatók.</p><button class="mz-inline" ${attr(3)}>Tudástár ↗</button></li></ol>`+note('A tények felhasználhatósága nem jelenti, hogy minden válaszban minden tény szerepel. Az aktuális kérdéshez tartozó kontextus számít.')+link('stack','Gépterem és mintafutás','A technikai háttér olvasható nézete.',2,'engine');}
function talk(id){const t=topics.find(t=>t.id===id);if(!t)return missing();return heading('BESZÉLGETÉS A TÉMÁRÓL',t.question,'A kiválasztott megfigyelés kontextusát magunkkal hozzuk.','chat')+`<div class="mz-talk-context"><span class="overline">AMIBŐL INDULUNK</span><p>${t.finding}</p><small>${t.limit}</small></div>`+['Miből gondolod ezt?','Mi szól ellene?','Mit próbálhatnék ki?'].map((q,i)=>`<details class="mz-question"><summary>${q}</summary><p>${[`${t.days} közös mintanap és az összehasonlítás adja a bemutató alapját. A részletek a forrásmintánál olvashatók.`,t.limit,t.probe][i]}</p></details>`).join('')+note('Itt témához kötött, előre megírt beszélgetésindítókat próbálhatsz. A valódi chat és modellhívás nincs bekötve.')+link('book','Saját gondolatot írnék','A naplóoldalra visz.',0,'journal-door');}
function missing(){return empty('Ez a részlet nem található.','Az alsó menüből visszatérhetsz a négy fő oldalra.');}
export function mezoContent(domain,page){if(domain!=='mezo')return null;const [, ,view='',id='']=location.hash.slice(1).split('/');let html;
 if(!view)html=[overview,predictions,character,knowledge][page]();
 else if(view==='pattern')html=pattern(id);else if(view==='investigate')html=investigate(id);else if(view==='experiment')html=experiment(id);else if(view==='forecast')html=forecast(id);else if(view==='dimension')html=dimension(id);else if(view==='conference')html=conference();else if(view==='team')html=team(id);else if(view==='feed')html=feed();else if(view==='audit')html=audit();else if(view==='engine')html=engine(id);else if(view==='coverage')html=coverage();else if(view==='coaching')html=coaching();else if(view==='coaching-detail')html=coachingDetail();else if(view==='fact')html=fact(id);else if(view==='memory')html=memory(id);else if(view==='memoir')html=memoir(id);else if(view==='graph')html=graph(id);else if(view==='layers')html=layers();else if(view==='talk')html=talk(id);
 else if(view==='conference-archive')html=heading('KORÁBBI KONZÍLIUM','Augusztus 30.','Egy újrakezdésről szóló mintadöntés.','chat')+note('A csapat egyetlen rövid reggeli lépés megfigyelését javasolta. Tartós karakterállításhoz még kevés adat volt.')+link('ring','A tovább figyelt minta',topics[2].title,0,'pattern','rhythm');
 else if(view==='new-fact')html=heading('SAJÁT TÉNY','Mondd el pontosan.','A saját bejegyzésed szerkeszthető és kikapcsolható marad.','book')+`<form id="mz-new-fact"><label class="mz-label">Amit szeretnél, hogy tudjak<textarea name="text" maxlength="1000" required placeholder="Például: csütörtökönként röplabdázom."></textarea></label>${action('Megőrzöm a demóban','type="submit"')}</form>`;
 else if(view==='tone')html=heading('ÍGY BESZÉLJ VELEM','A hang is személyes.','A saját preferenciád, nem Mezo következtetése rólad.','chat')+`<form id="mz-tone"><label class="mz-label">Amit szívesen hallasz<textarea name="text" required maxlength="1000">${safe(state.tone)}</textarea></label>${action('Preferencia mentése','type="submit"')}</form>`+note('A demó eltárolja a szöveget, de nem generál vele valódi AI-választ.');
 else if(view==='journal-door')html=heading('SAJÁT GONDOLAT','A te szavaiddal.','A naplóban szabadon leírhatod, mi kapcsolódik ehhez.','book')+`<button class="mz-action" data-open="journal">Naplóbejegyzés írása</button>`;
 else html=missing();
 return `<div class="mezo-world">${view?`<button class="mz-back" ${attr(page)}>‹ ${roots[page]}</button>`:''}${html}${foot()}</div>`;
}
export function mezoDetail(){return location.hash.startsWith('#mezo/')&&location.hash.split('/').length>2;}
export function initMezo(options){callbacks=options;
 document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;
 if(d.mzLink){location.hash=d.mzLink;return;}
 if(d.mzFilter){if(d.mzFilter==='patterns')patternFilter=d.value;if(d.mzFilter==='forecasts')forecastFilter=d.value;if(d.mzFilter==='conference')conferenceMode=d.value;callbacks.refresh();}
 if(d.mzPattern){decidePattern(state,d.mzPattern,d.decision);callbacks.refresh();react('connect');}
 if(d.mzStart){startExperiment(state,d.mzStart);callbacks.refresh();react('connect');}
 if(d.mzAdvance){advanceExperiment(state,d.mzAdvance);callbacks.refresh();}
 if(d.mzFeedback){state.feedback[d.mzFeedback]=d.value;callbacks.refresh();toast('A hasznossági visszajelzésed megérkezett.');}
 if(d.mzClaim){const c=state.claims.find(c=>c.id===d.mzClaim);if(d.value==='reject')c.status='retired';else c.feedback='agree';state.eventLog.push(`${d.value==='reject'?'Visszavontad':'Megerősítetted'}: ${c.text}`);callbacks.refresh();}
 if(d.mzFocus)document.getElementById(d.mzFocus)?.focus();
 if(d.mzCandidate){if(d.mzCandidate==='accept')acceptCandidate(state);else state.candidate='rejected';callbacks.refresh();}
 if(d.mzToggle){const f=state.facts.find(f=>f.id===d.mzToggle);f.active=!f.active;callbacks.refresh();}
 });
 document.addEventListener('input',e=>{if(e.target.id==='mz-fact-search'){factQuery=e.target.value;document.querySelector('#mz-fact-results').innerHTML=factRows();}if(e.target.id==='mz-memory-search'){memoryQuery=e.target.value;document.querySelector('#mz-memory-results').innerHTML=memoryRows();}});
 document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('[data-mz-correction],[data-mz-experiment-note],[data-mz-fact-edit],#mz-tone,#mz-new-fact'))return;e.preventDefault();const form=new FormData(f),text=String(form.get('text')||'').trim();
 if(f.dataset.mzCorrection){if(!text)return;correctClaim(state,f.dataset.mzCorrection,text);state.eventLog.push('Pontosítást küldtél: '+text);}
 if(f.dataset.mzExperimentNote)state.experiments.find(e=>e.topic===f.dataset.mzExperimentNote).note=String(form.get('note')||'').trim();
 if(f.dataset.mzFactEdit){if(!text)return;state.facts.find(t=>t.id===f.dataset.mzFactEdit).text=text;}
 if(f.id==='mz-tone'){if(!text)return;state.tone=text;}
 if(f.id==='mz-new-fact'){if(!text)return;const id='manual-'+state.facts.length;state.facts.push({id,text,source:'Saját bejegyzés',category:'Saját',active:true});location.hash=path(3,'fact',id);}
 callbacks.refresh();toast('Megőriztem a demóban.');react('connect',2000);
 });
 document.querySelector('#restart').addEventListener('click',()=>{state=createMezo();patternFilter='all';forecastFilter='all';factQuery='';memoryQuery='';callbacks.refresh();});
}
